    'global.out_of': 'de 10',
    'global.trend_accumulating': 'Datos de tendencia en recopilación - el gráfico aparecerá después de recopilar más datos diarios.',
    'global.trend_stable': 'Estable — no se detectaron cambios significativos en el periodo de monitoreo',
