    'methodology.source.vdem_desc': 'V-Dem Country-Year Dataset v16 — Rechtsstaatlichkeitsindex, Politischer Korruptionsindex und Bewertung einer rigorosen und unparteiischen öffentlichen Verwaltung. Lizenziert unter CC-BY-SA 4.0 (Coppedge et al., DOI 10.23696/vdemds26).',
    'methodology.source.gpi': 'Globaler Friedensindex (IEP)',
